impl Solution {
    pub fn max_k_segments_sum(nums: Vec<i64>, m: usize, k: usize) -> i128 {
        let n = nums.len();
        let mut dp = vec![vec![-1i128; k + 1]; n + 1];
        dp[0][0] = 0;

        for i in 1..=n {
            for j in 0..=k {
                if dp[i-1][j] != -1 {
                    let mut current = dp[i-1][j];
                    let mut sum = 0;
                    let mut len = 0;
                    for l in (0..i).rev() {
                        sum += nums[l];
                        len += 1;
                        if len > m {
                            break;
                        }
                        if j + 1 <= k {
                            if current + sum > dp[i][j + 1] {
                                dp[i][j + 1] = current + sum;
                            }
                        }
                    }
                }
            }
        }

        let mut result = -1i128;
        for i in 0..=n {
            for j in 0..=k {
                if dp[i][j] > result {
                    result = dp[i][j];
                }
            }
        }
        result
    }
}
